'use strict';

function _render(context, options) {

	var $ = context.jQuery,
		PubSub = context.PubSub;

	//Create the question
	var question = options.question ? options.question : 'text',
		name = options.name ? options.name : question;

	//HTML
	var $html = $(
		'<div class="form-group">' +
		'<h3>' + question + '</h3>' +
			$(this).addClass('form-control f3-text')
				.attr('name', name)
				.attr('data-options', JSON.stringify(options))
				.prop('outerHTML') +
		'</div>'
	);

	//Bind change
	$html.find('input').on('change', function(){

		//Publish the event
		PubSub.publish('f3.text', {
			'trigger': this,
			'event': 'change'
		});

	}).on('click', function(){

		//Publish the event
		PubSub.publish('f3.text', {
			'trigger': this,
			'event': 'click'
		});

	});

	return $html;

}

function _read(options, value) {

	return {
		question: options.question || 'text',
		name: options.name || options.question,

		text: value,
		value: value
	};

}

module.exports = {
	render: _render,
	read: _read,
	name: 'text'
};
